"""A least-recently-used cache with optional time-to-live (TTL)."""
import time
from collections import OrderedDict


# Sentinel marking "use the cache's default ttl" in ``put``.
USE_DEFAULT = object()


class LRUCache:
    def __init__(self, capacity, ttl=None, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be greater than 0")
        self.capacity = capacity
        self._default_ttl = ttl
        self._clock = clock
        # Each entry maps key -> (value, stored_at, ttl)
        # ``ttl`` of None means the entry never expires.
        self._items = OrderedDict()

    def _expired(self, key, now):
        """True if the entry for ``key`` has reached the end of its lifetime."""
        _, stored_at, ttl = self._items[key]
        if ttl is None:
            return False
        return now - stored_at >= ttl

    def _purge_expired(self, now):
        """Remove every expired entry from the cache."""
        expired = [k for k in self._items if self._expired(k, now)]
        for k in expired:
            del self._items[k]

    def get(self, key, default=None):
        """Return the value and mark the entry as most recently used.

        Expired entries behave as absent: the ``default`` is returned and the
        lifetime is not restarted.
        """
        now = self._clock()
        if key in self._items and not self._expired(key, now):
            self._items.move_to_end(key)
            return self._items[key][0]
        return default

    def peek(self, key, default=None):
        """Return the value without touching the order or the lifetime."""
        now = self._clock()
        if key in self._items and not self._expired(key, now):
            return self._items[key][0]
        return default

    def put(self, key, value, ttl=USE_DEFAULT):
        """Insert or update an entry.

        ``ttl`` overrides the cache default for this entry. Passing ``ttl=None``
        makes this entry never expire, even when the cache has a default ttl.
        A non-None ``ttl`` must be greater than 0, else ``ValueError`` is raised
        and nothing is stored.
        """
        if ttl is USE_DEFAULT:
            effective_ttl = self._default_ttl
        else:
            effective_ttl = ttl

        if effective_ttl is not None and effective_ttl <= 0:
            raise ValueError("ttl must be greater than 0")

        now = self._clock()
        # Expired entries never cost a live entry its place: drop them first.
        self._purge_expired(now)

        if key in self._items:
            # Replacing a live entry: restart its lifetime and make it MRU.
            self._items[key] = (value, now, effective_ttl)
            self._items.move_to_end(key)
        else:
            if len(self._items) >= self.capacity:
                self._items.popitem(last=False)
            self._items[key] = (value, now, effective_ttl)

    def keys(self):
        """Keys from least to most recently used, excluding expired entries."""
        now = self._clock()
        return [k for k in self._items if not self._expired(k, now)]

    def __contains__(self, key):
        now = self._clock()
        return key in self._items and not self._expired(key, now)

    def __len__(self):
        now = self._clock()
        return sum(1 for k in self._items if not self._expired(k, now))
